bool OrcaServiceStubDispatch::Accept(
    OrcaService* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kOrcaService_BindEditor_Name: {

      DCHECK(message->is_serialized());
      internal::OrcaService_BindEditor_Params_Data* params =
          reinterpret_cast<internal::OrcaService_BindEditor_Params_Data*>(
              message->mutable_payload());
      
      
      // Validation for OrcaService.0
      bool success = true;
      ::mojo::PendingAssociatedRemote<TextActuator> p_text_actuator{};
      ::mojo::PendingAssociatedRemote<TextQueryProvider> p_text_query_provider{};
      ::mojo::PendingAssociatedReceiver<EditorClientConnector> p_client_connector{};
      ::mojo::PendingAssociatedReceiver<EditorEventSink> p_event_sink{};
      OrcaService_BindEditor_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_text_actuator =
            input_data_view.TakeTextActuator<decltype(p_text_actuator)>();
      }
      if (success) {
        p_text_query_provider =
            input_data_view.TakeTextQueryProvider<decltype(p_text_query_provider)>();
      }
      if (success) {
        p_client_connector =
            input_data_view.TakeClientConnector<decltype(p_client_connector)>();
      }
      if (success) {
        p_event_sink =
            input_data_view.TakeEventSink<decltype(p_event_sink)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            OrcaService::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->BindEditor(        
        std::move(p_text_actuator), 
        std::move(p_text_query_provider), 
        std::move(p_client_connector), 
        std::move(p_event_sink));
      return true;
    }
  }
  return false;
}

