// static
bool UnionTraits<::ash::orca::mojom::TextQueryResponse::DataView, ::ash::orca::mojom::TextQueryResponsePtr>::Read(
    ::ash::orca::mojom::TextQueryResponse::DataView input,
    ::ash::orca::mojom::TextQueryResponsePtr* output) {
  using UnionType = ::ash::orca::mojom::TextQueryResponse;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kResults: {
      std::vector<::ash::orca::mojom::TextQueryResultPtr> result_results;
      if (!input.ReadResults(&result_results))
        return false;

      *output = UnionType::NewResults(
          std::move(result_results));
      break;
    }
    case Tag::kError: {
      ::ash::orca::mojom::TextQueryErrorPtr result_error;
      if (!input.ReadError(&result_error))
        return false;

      *output = UnionType::NewError(
          std::move(result_error));
      break;
    }
    default:

      return false;
  }
  return true;
}

